def berth_allocations(tonnage_cap, vessels):
    if tonnage_cap < 0:
        raise ValueError("negative cap")
    docked = []
    flags = []
    peak = 0
    for arrive, depart, tons in vessels:
        if depart <= arrive or tons < 0:
            raise ValueError("invalid vessel")
        cur_tons = sum(entry[2] for entry in docked)
        docked = [entry for entry in docked if entry[1] > arrive]
        if cur_tons + tons <= tonnage_cap:
            docked.append([arrive, depart, tons])
            if cur_tons + tons > peak:
                peak = cur_tons + tons
            flags.append(True)
        else:
            flags.append(False)
    return [flags, peak]

def payload_slice_hits(segments, offset, span):
    if offset < 0 or span < 0:
        raise ValueError("invalid slice")
    cursor = 0
    query_end = offset + span
    overlaps = []
    for kind, length in segments:
        if length < 0 or kind not in ("data", "meta"):
            raise ValueError("invalid segment")
        seg_end = cursor + length
        if kind == "data":
            lo_pos = max(offset, cursor)
            hi_pos = min(query_end, seg_end)
            overlaps.append(max(0, hi_pos - lo_pos))
        cursor = seg_end
    return overlaps

def tariff_window_charge(open_hr, close_hr, bookings):
    if close_hr <= open_hr:
        raise ValueError("invalid window")
    loads = [0] * (close_hr - open_hr)
    for start_hr, end_hr, rate in bookings:
        if end_hr <= start_hr:
            continue
        if start_hr >= open_hr and end_hr <= close_hr:
            for hr_val in range(start_hr, end_hr):
                loads[hr_val - open_hr] += rate
    return loads

def escrow_ledgers(records):
    open_snapshots = {}
    shared_total = 0
    released = []
    for op_name, escrow_id, amount in records:
        if op_name == "open":
            if escrow_id in open_snapshots:
                raise ValueError("already open")
            open_snapshots[escrow_id] = shared_total
        elif op_name == "credit":
            if escrow_id not in open_snapshots:
                raise ValueError("not open")
            shared_total += amount
        elif op_name == "release":
            if escrow_id not in open_snapshots:
                raise ValueError("not open")
            released.append([escrow_id, shared_total - open_snapshots.pop(escrow_id)])
        elif op_name == "void":
            if escrow_id not in open_snapshots:
                raise ValueError("not open")
            open_snapshots.pop(escrow_id)
        else:
            raise ValueError("unknown op")
    return released

def sensor_epoch_deltas(readings):
    highs = {}
    deltas = []
    for kind, sensor_id, value in readings:
        if kind == "sample":
            if sensor_id not in highs:
                highs[sensor_id] = value
                deltas.append(0)
            elif value > highs[sensor_id]:
                deltas.append(value - highs[sensor_id])
                highs[sensor_id] = value
            else:
                deltas.append(0)
        elif kind == "recal":
            highs.clear()
        else:
            raise ValueError("unknown kind")
    return deltas

def stage_drawdowns(steps):
    level = 0
    stage_min = None
    closed = []
    for tag, delta in steps:
        if tag == "step":
            level += delta
            if stage_min is None or level < stage_min:
                stage_min = level
        elif tag == "pause":
            level = 0
            stage_min = None
        elif tag == "close":
            closed.append(stage_min)
            level = 0
            stage_min = None
        else:
            raise ValueError("unknown tag")
    return closed

def voucher_redemptions(stock, baskets):
    pool = {}
    for sku, count in stock.items():
        if count < 0:
            raise ValueError("negative stock")
        pool[sku] = count
    reports = []
    for basket in baskets:
        ok_flag = True
        for sku, qty in basket:
            if qty < 1:
                raise ValueError("invalid qty")
            if pool.get(sku, 0) < qty:
                ok_flag = False
                break
            pool[sku] -= qty
        reports.append(sum(pool.values()) if ok_flag else -1)
    return reports

def ward_endorsements(ballots, min_wards):
    if min_wards < 1:
        raise ValueError("invalid min_wards")
    counts = {}
    for ward, candidate in ballots:
        if ward and candidate:
            counts[candidate] = counts.get(candidate, 0) + 1
    qualified = [[cand, num] for cand, num in counts.items() if num >= min_wards]
    qualified.sort(key=lambda item: (-item[1], item[0]))
    return qualified

def bipartite_pair_weights(left_rows, right_rows):
    left_map = {key: (team, weight) for key, team, weight in left_rows}
    right_map = {key: (team, weight) for key, team, weight in right_rows}
    pair_count = 0
    weight_sum = 0
    for key, (left_team, left_w) in left_map.items():
        if key in right_map:
            right_team, right_w = right_map[key]
            if left_team != right_team:
                pair_count += 1
                weight_sum += left_w + right_w
    return [pair_count, weight_sum]

def workqueue_promotions(limit, commands):
    if limit < 1:
        raise ValueError("invalid limit")
    queue = []
    dropped = []
    for cmd, job in commands:
        if cmd == "push":
            if job not in queue:
                if len(queue) == limit:
                    dropped.append(queue.pop(0))
                queue.append(job)
        elif cmd == "pop":
            if queue:
                queue.pop(0)
        else:
            raise ValueError("unknown cmd")
    return [dropped, queue]

def audit_first_ranks(logs):
    totals = {}
    first_seen = {}
    has_valid = set()
    for idx, (actor, valid_flag, points) in enumerate(logs):
        if valid_flag not in (0, 1):
            raise ValueError("invalid flag")
        if actor not in first_seen:
            first_seen[actor] = idx
        if valid_flag == 1:
            has_valid.add(actor)
            totals[actor] = totals.get(actor, 0) + points
    ranked = sorted(
        has_valid,
        key=lambda actor: (-totals[actor], first_seen[actor]),
    )
    return [[actor, totals[actor]] for actor in ranked]

def budgeted_grant_order(proposals, dept_budgets):
    budgets = {}
    for dept, amt in dept_budgets.items():
        if amt < 0:
            raise ValueError("negative budget")
        budgets[dept] = amt
    accepted = []
    for title, dept, _prio, cost in proposals:
        if cost < 0:
            raise ValueError("negative cost")
        if dept in budgets and cost <= budgets[dept]:
            budgets[dept] -= cost
            accepted.append(title)
    return accepted

def fsm_door_cycles(commands):
    state = "closed"
    cycles = 0
    for cmd in commands:
        if cmd not in ("open", "close", "lock", "unlock"):
            raise ValueError("unknown command")
        if cmd == "open" and state != "locked":
            state = "open"
        elif cmd == "close":
            state = "closed"
            cycles += 1
        elif cmd == "lock":
            state = "locked"
        elif cmd == "unlock" and state == "locked":
            state = "closed"
    return [state, cycles]

def frame_byte_decoder(stream):
    mode = "plain"
    first_half = 0
    decoded = []
    for byte_val in stream:
        if byte_val < 0 or byte_val > 255:
            raise ValueError("byte out of range")
        if byte_val == 254:
            mode = "esc"
        elif byte_val == 255:
            mode = "pair_one"
        elif mode == "esc":
            decoded.append(byte_val ^ 32)
            mode = "plain"
        elif mode == "pair_one":
            first_half = byte_val
            mode = "pair_two"
        elif mode == "pair_two":
            decoded.append((first_half + byte_val) % 256)
            mode = "plain"
        else:
            decoded.append(byte_val)
    return decoded

def retry_backoff_sim(base_delay, max_delay, outcomes):
    if base_delay < 1 or max_delay < base_delay:
        raise ValueError("invalid delays")
    cur_delay = base_delay
    ok_count = 0
    total_wait = 0
    for label in outcomes:
        if label not in ("ok", "temp", "fatal"):
            raise ValueError("unknown outcome")
        if label == "ok":
            ok_count += 1
        elif label == "temp":
            cur_delay = min(max_delay, cur_delay * 2)
            total_wait += cur_delay
        else:
            continue
    return [ok_count, total_wait]

def sliding_singleton_counts(values, width):
    if width < 1:
        raise ValueError("invalid width")
    if len(values) < width:
        return []
    return [len(set(values[pos : pos + width])) for pos in range(len(values) - width + 1)]

def bounded_span_count(nums, tolerance, max_len):
    if tolerance < 0 or max_len < 1:
        raise ValueError("invalid bounds")
    total = 0
    for left in range(len(nums)):
        for right in range(left, min(len(nums), left + max_len)):
            if abs(nums[right] - nums[left]) <= tolerance:
                total += 1
    return total

def ema_breach_streaks(samples, weight, hi_mark):
    if weight < 1 or weight > 10:
        raise ValueError("invalid weight")
    avg = 0
    cur_streak = 0
    max_streak = 0
    total_breaches = 0
    for val in samples:
        avg = (weight * val + (10 - weight) * avg) // 10
        if avg > hi_mark:
            cur_streak += 1
            total_breaches += 1
            max_streak = max(max_streak, cur_streak)
        else:
            cur_streak = 0
    return [max_streak, total_breaches]

def scoped_tag_validator(max_depth, tokens):
    if max_depth < 1:
        raise ValueError("invalid max_depth")
    depth = 0
    peak = 0
    for kind, tag in tokens:
        if kind not in ("open", "close", "self") or not tag:
            raise ValueError("invalid token")
        if kind == "open":
            depth += 1
            if depth > max_depth:
                return [False, peak]
            peak = max(peak, depth)
        elif kind == "close":
            if depth == 0:
                return [False, peak]
            depth -= 1
    return [depth == 0, peak]

def min_paren_repairs(symbols):
    pairs = {")": "(", "]": "["}
    allowed = {"(", ")", "[", "]"}
    for sym in symbols:
        if sym not in allowed:
            raise ValueError("invalid symbol")
    stack = []
    closer_repairs = 0
    for sym in symbols:
        if sym in ("(", "["):
            stack.append(sym)
        elif not stack:
            closer_repairs += 1
        else:
            top = stack.pop()
            if top != pairs[sym]:
                closer_repairs += 1
    return [closer_repairs, len(stack)]

def callstack_exclusive_time(trace):
    entered_at = {}
    exclusive = {}
    prev_ts = 0
    for idx, (kind, func_name, cur_ts) in enumerate(trace):
        if kind not in ("enter", "exit") or not func_name or cur_ts < 0:
            raise ValueError("invalid event")
        if idx > 0 and cur_ts < prev_ts:
            raise ValueError("non-monotone timestamp")
        if kind == "enter":
            entered_at[func_name] = cur_ts
            exclusive.setdefault(func_name, 0)
        else:
            if func_name not in entered_at:
                raise ValueError("mismatched exit")
            exclusive[func_name] += cur_ts - entered_at.pop(func_name)
        prev_ts = cur_ts
    if entered_at:
        raise ValueError("unclosed call")
    return sorted([name, val] for name, val in exclusive.items())

def coalesce_signed_runs(runs):
    merged = []
    for label, delta in runs:
        if not label:
            raise ValueError("empty label")
        if merged and merged[-1][0] == label:
            merged[-1][1] += delta
        elif delta != 0:
            merged.append([label, delta])
    return [item for item in merged if item[1] != 0]

def ordered_union_versions(streams):
    best_ver = {}
    order = []
    for stream in streams:
        for pkg, ver in stream:
            if not pkg:
                raise ValueError("empty pkg")
            if pkg not in order:
                order.append(pkg)
            if ver >= 0:
                best_ver[pkg] = ver
    return [[pkg, best_ver[pkg]] for pkg in order if pkg in best_ver]

def k_way_quorum_merge(sorted_lists, min_lists):
    if min_lists < 1:
        raise ValueError("invalid min_lists")
    list_counts = {}
    for seq in sorted_lists:
        for idx in range(1, len(seq)):
            if seq[idx] < seq[idx - 1]:
                raise ValueError("unsorted input")
        for val in seq:
            list_counts[val] = list_counts.get(val, 0) + 1
    return sorted(val for val, num in list_counts.items() if num >= min_lists)
